import{_ as t,o as i,c as u,a3 as a,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/benutzer-einstellungen/schid-verwaltung-benutzer-benutzerverwaltung-anmeldung.png",s="/bilder/benutzer-einstellungen/verwalung-benutzer-benutzerverwaltung-uebersicht.png",g="/bilder/benutzer-einstellungen/verwaltung-benutzer-benutzerverwaltung-rechtsklick.png",d="/bilder/benutzer-einstellungen/verwaltung-benutzer-benutzerverwaltung-neue-person.png",o="/bilder/benutzer-einstellungen/verwaltung-benutzer-benutzerverwaltung-benutzergruppen.png",f=JSON.parse('{"title":"Benutzer und Berechtigungen verwalten","description":"","frontmatter":{"title":"Benutzer und Berechtigungen verwalten","source_pageid":280,"source_revision":6115},"headers":[],"relativePath":"administration/benutzer-einstellungen/benutzerverwaltung-verwaltung-schule.md","filePath":"administration/benutzer-einstellungen/benutzerverwaltung-verwaltung-schule.md"}'),h={name:"administration/benutzer-einstellungen/benutzerverwaltung-verwaltung-schule.md"};function c(p,r,b,z,m,w){return i(),u("div",null,[...r[0]||(r[0]=[a('<h1 id="benutzer-und-berechtigungen-verwalten" tabindex="-1">Benutzer und Berechtigungen verwalten <a class="header-anchor" href="#benutzer-und-berechtigungen-verwalten" aria-label="Permalink to &quot;Benutzer und Berechtigungen verwalten&quot;">​</a></h1><p>Legen Sie Benutzer an und ordnen Sie ihnen die passenden Benutzergruppen und Berechtigungen zu. Die Benutzerverwaltung erfordert eine erneute Anmeldung mit den dafür vorgesehenen Rechten.</p><h2 id="uberblick" tabindex="-1">Überblick <a class="header-anchor" href="#uberblick" aria-label="Permalink to &quot;Überblick&quot;">​</a></h2><p><a href="/bilder/benutzer-einstellungen/schid-verwaltung-benutzer-benutzerverwaltung-anmeldung.png"><img src="'+l+'" alt="Anmeldung in der Benutzerverwaltung" loading="lazy"></a></p><p><em>Anmeldung in der Benutzerverwaltung</em></p><p>Über den Menüpunkt <strong>Benutzerverwaltung</strong> können Benutzer und zugehörige Zugriffsberechtigungen verwaltet werden.</p><p>In der Regel dürfen nur Administratorinnen und Administratoren Benutzer und Berechtigungen verwalten. Beim Öffnen der Benutzerverwaltung müssen Sie sich aus Sicherheitsgründen erneut anmelden.</p><p><a href="/bilder/benutzer-einstellungen/verwalung-benutzer-benutzerverwaltung-uebersicht.png"><img src="'+s+'" alt="Die Benutzerverwaltung zeigt die eingerichteten Benutzer." loading="lazy"></a></p><p><em>Die Benutzerverwaltung zeigt die eingerichteten Benutzer.</em></p><p>Die Übersicht zeigt die bereits angelegten Personen. Sie enthält den <strong>Benutzernamen</strong> für die Anmeldung, den Namen der Person sowie Angaben zur Administrationsebene und zum <strong>Benutzertyp</strong>.</p><p>Die Überschriften der Spalten können durch Anklicken und Ziehen der Überschriftenfelder neu geordnet werden. Auf der rechten Seite können die einzelnen Parameter des aktuell markierten Datensatzes betrachtet werden.</p><p>Aktivieren Sie unten rechts die <strong>Login-Historie</strong>, um die letzten An- und Abmeldezeiten des ausgewählten Benutzers anzuzeigen.</p><h2 id="bearbeitung" tabindex="-1">Bearbeitung <a class="header-anchor" href="#bearbeitung" aria-label="Permalink to &quot;Bearbeitung&quot;">​</a></h2><p><a href="/bilder/benutzer-einstellungen/verwaltung-benutzer-benutzerverwaltung-rechtsklick.png"><img src="'+g+'" alt="Die Rechte Maustaste öffnet ein Kontextmenü." loading="lazy"></a></p><p><em>Die <code>Rechte Maustaste</code> öffnet ein Kontextmenü.</em></p><p>Über einen Rechtsklick in die freie Liste oder auf einen bestehenden Datensatz können Bearbeitungen vorgenommen werden.</p><p><a href="/bilder/benutzer-einstellungen/verwaltung-benutzer-benutzerverwaltung-neue-person.png"><img src="'+d+'" alt="Neuen Benutzer anlegen." loading="lazy"></a></p><p><em>Neuen Benutzer anlegen.</em></p><ul><li><strong>Passwort ändern</strong>: Das Passwort kann neu gesetzt werden, ohne dass das bisherige Passwort benötigt wird.</li><li><strong>Benutzer löschen</strong>: Der Benutzer wird nach Bestätigung mit allen Berechtigungen entfernt.</li><li><strong>Benutzer bearbeiten</strong>: Änderungen der Attribute können vorgenommen werden.</li><li><strong>Neuen Benutzer anlegen</strong>: Die Schaltfläche erstellt einen neuen Datensatz und öffnet das Feld zur Auswahl der Attribute.</li></ul><p>Der neu angelegten Person wird eine Art zugewiesen. Wenn eine Person über die Auswahl <strong>Lehrkraft</strong> aus dem Kollegium ausgewählt wird, wird das Kürzel aus der Datenbank gewählt.</p><p>Bei der Auswahl <strong>Allgemeine Benutzerin/allgemeiner Benutzer</strong> kann ein selbstgewählter Benutzername vergeben werden.</p><p>Wählen Sie anschließend eine oder mehrere <strong>Benutzergruppen</strong> aus. Der Benutzer erhält dadurch die für diese Gruppen voreingestellten Berechtigungen.</p><h2 id="benutzergruppen" tabindex="-1">Benutzergruppen <a class="header-anchor" href="#benutzergruppen" aria-label="Permalink to &quot;Benutzergruppen&quot;">​</a></h2><p><a href="/bilder/benutzer-einstellungen/verwaltung-benutzer-benutzerverwaltung-benutzergruppen.png"><img src="'+o+'" alt="Über Benutzergruppen lassen sich für eine Gruppe Berechtigungen vergeben." loading="lazy"></a></p><p><em>Über Benutzergruppen lassen sich für eine Gruppe Berechtigungen vergeben.</em></p><p>Über den Reiter <strong>Benutzergruppen bearbeiten</strong> können diese angelegt, definiert oder bearbeitet werden.</p><p>So kann sichergestellt werden, dass einzelne Gruppen in bestimmten Bereichen nur einzelne Berechtigungen erhalten.</p><p>Diese Benutzergruppen können dann als Vorlagen einzelnen Benutzern zugeordnet werden, sodass nicht für jede Person einzeln alle Berechtigungen gesetzt werden müssen.</p><p>Werden einzelne Berechtigungen nicht erteilt, ist es möglich, dass für diese Benutzergruppe Datensätze, Schaltflächen, Funktionen oder Übersichten nicht angezeigt werden.</p><p>Der Haken für die Admin-Gruppe setzt sofort alle Berechtigungen.</p>',30),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Über SchILD-NRW lassen sich Benutzergruppen mit Rechten definieren und SchILD-Nutzern zuweisen. Hierüber lassen sich auch sehr hohe Rechte vergeben. Achten Sie bitte darauf, dass Sie auch über Benutzergruppen nur Rechte an Nutzer vergeben, die diese benötigen und haben sollen!")],-1),e("p",null,[n("Mit "),e("strong",null,"Alle Lehrkräfte übernehmen"),n(" legen Sie nach einer Bestätigung für jede Lehrkraft ein Benutzerkonto an. Diese Konten erhalten die Berechtigungen der Benutzergruppe "),e("strong",null,"Lehrer"),n(".")],-1),e("p",null,"Dabei wird als Passwort der Benutzername eingesetzt, sodass bei der ersten Anmeldung dieses Passwort durch ein neues ersetzt werden soll.",-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Es empfiehlt sich nur dann Benutzer für das gesamte Kollegium anzulegen, wenn auch eine entsprechende Schulung erfolgt ist und eine entsprechende Infrastruktur zum Zugriff im Haus vorliegt. Noten- und Fehlzeiteneintragungen können auch über ein externes Modul bearbeitet werden.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Benutzerverwaltung_(Verwaltung_Schule)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6115.")],-1)])])}const v=t(h,[["render",c]]);export{f as __pageData,v as default};
